@-moz-document domain("promodescuentos.com") {
.subNav, .nav,.groupPromo--bg, .subNav--light {
    background-color: #292929!important;
}

.subNav {
    border-bottom: 1px solid #291F11;
    position: relative;
}

.scrollBox-item {
  margin-right: 8px; /* Espacio horizontal entre elementos */
}

/* Para asegurar que el último elemento no tenga margen a la derecha */
.scrollBox-item:last-child {
  margin-right: 0;
}


